package com.example.bodega.venta.controller;
import com.example.bodega.security.SecurityUser; import com.example.bodega.venta.dto.*; import com.example.bodega.venta.enums.EstadoVenta; import com.example.bodega.venta.service.VentaService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.time.LocalDate;
@RestController @RequestMapping("/api/ventas") @RequiredArgsConstructor
public class VentaController {private final VentaService service;@PostMapping @PreAuthorize("hasAnyRole('ADMIN','CAJERO')") public ResponseEntity<VentaResponse> crear(@Valid @RequestBody VentaRequest r,@RequestHeader("Idempotency-Key") String key,@AuthenticationPrincipal SecurityUser u){return ResponseEntity.status(HttpStatus.CREATED).body(service.crear(r,key,u.id()));}@GetMapping @PreAuthorize("hasAnyRole('ADMIN','CAJERO')") public Page<VentaResponse> listar(@RequestParam(required=false) LocalDate desde,@RequestParam(required=false) LocalDate hasta,@RequestParam(required=false) EstadoVenta estado,@RequestParam(required=false) Long usuarioId,@PageableDefault(size=20,sort="fecha",direction=Sort.Direction.DESC) Pageable pageable){return service.listar(desde,hasta,estado,usuarioId,pageable);}@GetMapping("/{id}") @PreAuthorize("hasAnyRole('ADMIN','CAJERO')") public VentaResponse obtener(@PathVariable Long id){return service.obtener(id);}@PostMapping("/{id}/anulacion") @PreAuthorize("hasRole('ADMIN')") public VentaResponse anular(@PathVariable Long id,@Valid @RequestBody AnulacionRequest r,@AuthenticationPrincipal SecurityUser u){return service.anular(id,r,u.id());}}
